insert into public.passages (id, subject_id, label, body_html, sort_order) values ('psg-tka-bahasa-indonesia-sma-bacaan_01', 'sub-bahasa-indonesia-sma', 'Teks untuk soal nomor 1 s.d. 4', '<p><strong>Teks untuk soal nomor 1 s.d. 4</strong></p><p>Lautan mengalami ancaman pemanasan dan menjadi semakin asam karena kita terus memompa lebih banyak CO<sub>2</sub> ke atmosfer. Selain itu, lautan juga menghadapi ancaman lain dari manusia, yakni penggunaan plastik. Kehidupan modern saat ini didominasi oleh kemasan makanan berbahan plastik yang diolah dengan teknologi tinggi dan digunakan setiap hari oleh masyarakat. Dalam sebuah laporan telah disebutkan bahwa pada tahun 2050 sampah plastik di laut akan lebih banyak daripada jumlah ikan apabila kecenderungan ini terus berlanjut. Hal tersebut merupakan sebuah ancaman besar.</p><p>Dibutuhkan tindakan skala besar untuk berpindah dari kecenderungan tersebut mengingat banyak pihak yang terlibat dalam bidang pekerjaan ini. Masyarakat sektor swasta dan masyarakat sipil perlu mobilisasi untuk menangkap peluang ekonomi lain di luar dari pengelolaan plastik.</p><p>Solusi tersebut tidak mudah. Fakta bahwa harga minyak yang rendah mengakibatkan biaya yang dibutuhkan untuk daur ulang plastik jauh lebih mahal daripada memproduksi yang baru. Kondisi lain yang menunjukkan ekonomi di negara berkembang tumbuh lebih besar menjadikan penggunaan plastik juga meningkat. Solusi yang dibutuhkan adalah cara kita menggunakan plastik. Misalnya dengan mengurangi penggunaan plastik dalam kemasan atau menggunakannya kembali sebanyak yang kita bisa.</p><p>Produsen plastik juga dapat membantu dalam pengelolaan plastik, seperti memproduksi barang-barang plastik yang dapat digunakan kembali atau beralih ke plastik yang dapat dijadikan kompos. Solusi apa pun akan membawa perubahan besar dalam cara menggunakan produk yang terbuat dari plastik.</p>', 0) on conflict (id) do update set subject_id = excluded.subject_id, label = excluded.label, body_html = excluded.body_html, sort_order = excluded.sort_order;
insert into public.passages (id, subject_id, label, body_html, sort_order) values ('psg-tka-bahasa-indonesia-sma-bacaan_02', 'sub-bahasa-indonesia-sma', 'Teks untuk soal 5 s.d. 7', '<p><strong>Teks untuk soal 5 s.d. 7</strong></p><p>“E...gurumu itu orang desa ini juga. Pasti tahu bahwa saat ini musim <em>maddongi</em> (<em>mengusir burung saat buah padi mulai menguning</em>). Besok kau menghadap, sampaikan bahwa kau membantu Ayah di sawah. Nah, pasti gurumu mengerti mengapa kamu tidak ke sekolah.”</p><p>Aku terpana. Jawaban Ayah benar-benar membuatku hampir menangis histeris. Bagaimana tidak. Lomba semakin dekat, sementara masih banyak materi yang belum aku paham. Terbayang aku akan hancur dan tidak bisa bersaing dengan siswa sekolah lain. Ingin rasanya aku berteriak agar Ayahku tahu bagaimana kacaunya pikiranku. Namun, aku sadar bahwa ini adalah perbuatan yang tidak akan menyelesaikan masalah. Malah akan semakin membuat Ayahku geram. Otakku terus berpikir untuk mencari solusi terbaik. Sambil berjalan mengikuti Ayah dari belakang, aku mulai menyusun strategi. “Bagaimana kalau aku ke rumah <em>iyye-</em>ku (<em>nenek</em>), menyampaikan masalahku ini. Ya, hanya dia yang mampu menundukkan Ayah.”</p><p>Esok harinya, sepulang sekolah, kuayunkan sepedaku menuju rumah <em>iyye-</em>ku.</p><p>“Kenapa kamu lesu?” <em>Iyye</em> menanyakan keadaanku. Aku pun menceritakan semuanya kepada <em>iyye</em>.</p><p>“Ya sudah, tidak usah sedih. Nanti kusampaikan pada ayahmu. Kau ke dalam, makan dulu, baru pulang,” ujar <em>iyye</em>-ku.</p><p> (<em>Piala di Atas Dangau,</em> Muhammad Isrul, dengan penyesuaian)</p>', 1) on conflict (id) do update set subject_id = excluded.subject_id, label = excluded.label, body_html = excluded.body_html, sort_order = excluded.sort_order;
insert into public.passages (id, subject_id, label, body_html, sort_order) values ('psg-tka-bahasa-indonesia-sma-bacaan_03', 'sub-bahasa-indonesia-sma', 'Teks untuk soal nomor 8 s.d. 10', '<p><strong>Teks untuk soal nomor 8 s.d. 10</strong></p><p>Teks 1</p><p>Rhodamin B adalah zat pewarna yang tersedia di pasar untuk industri tekstil. Zat ini sering disalahgunakan sebagai zat pewarna makanan dan kosmetik di berbagai negara. Jenis makanan yang mengandung Rhodamin B di antaranya kerupuk, terasi, dan makanan ringan. Zat ini juga banyak ditemukan pada kembang gula, sirup, manisan, dawet, bubur, ikan asap, dan cendol. Tampilan makanan yang menggunakan zat ini cenderung menarik dan terkesan menawarkan cita rasa tinggi sehingga ketika harga jualnya tidak semahal tampilannya, banyak yang tertarik untuk membeli dan mengonsumsinya. Zat ini paling berbahaya bila dikonsumsi karena menyebabkan gangguan pada fungsi hati, bahkan kanker hati. Apabila mengonsumsi makanan yang mengandung Rhodamin B, dalam tubuh akan terjadi penumpukan lemak sehingga lama-kelamaan jumlahnya akan terus bertambah. Dampaknya baru akan kelihatan setelah puluhan tahun kemudian. Jika sudah masuk dalam tubuh, akan mengendap pada jaringan hati dan lemak, tidak dapat dikeluarkan, dan dalam jangka waktu lama bisa bersifat karsinogenik.</p><p>Teks 2</p><p>Rhodamin B berbentuk serbuk kristal, berwarna hijau atau ungu kemerahan, tidak berbau, dan dalam larutan akan berwarna merah terang berpendar atau berfluoresensi. Rhodamin B merupakan zat warna golongan <em>xanthenes dyes</em>, dan digunakan pada industri tekstil dan kertas, sebagai pewarna kain, kosmetika, produk pembersih mulut, dan sabun. Rhodamin B memiliki berbagai nama lain, antara lain: Tetra ethyl rhodamin; Rheoninine B, D, &amp; C; Red No. 19; Food Red 15; ADC Rhodamine B; Aizen Rhodamine; dan Brilliant Pink B. Rhodamin B mengandung senyawa klorin (Cl) yang merupakan senyawa halogen yang berbahaya dan reaktif. Jika tertelan, senyawa ini akan berusaha mencapai kestabilan dalam tubuh dengan cara mengikat senyawa lain dalam tubuh. Mengonsumsi bahan pangan yang mengandung Rhodamin B dalam jangka panjang dapat terakumulasi di dalam tubuh dan dapat menyebabkan gejala pembesaran hati dan ginjal, gangguan fungsi hati, kerusakan hati, gangguan fisiologis tubuh, bahkan dapat menyebabkan timbulnya kanker hati.</p>', 2) on conflict (id) do update set subject_id = excluded.subject_id, label = excluded.label, body_html = excluded.body_html, sort_order = excluded.sort_order;
insert into public.passages (id, subject_id, label, body_html, sort_order) values ('psg-tka-bahasa-indonesia-sma-bacaan_04', 'sub-bahasa-indonesia-sma', 'Dampak Ekonomi Digital terhadap Pertumbuhan Usaha Kecil dan Menengah (UKM)', '<p>Dampak Ekonomi Digital terhadap Pertumbuhan Usaha Kecil dan Menengah (UKM)</p><p>Ekonomi digital telah membawa perubahan besar dalam berbagai aspek bisnis, terutama bagi Usaha Kecil dan Menengah (UKM). Dengan adanya teknologi digital, UKM kini memiliki peluang lebih besar untuk berkembang dan bersaing di pasar yang lebih luas. Transformasi ini didorong oleh beberapa faktor utama, seperti perkembangan <em>e-commerce</em>, sistem pembayaran digital, pemasaran berbasis data, serta pemanfaatan teknologi berbasis kecerdasan buatan (<em>artificial intelligence</em>).</p><p>Salah satu perubahan signifikan dalam ekonomi digital adalah kemudahan akses ke platform <em>e-commerce</em>. UKM yang sebelumnya hanya mengandalkan toko fisik kini dapat menjual produknya melalui berbagai <em>marketplace </em>daring. Hal ini memungkinkan mereka menjangkau konsumen di luar wilayah lokal, bahkan hingga ke pasar internasional. Dengan biaya operasional yang lebih rendah dibandingkan toko fisik, UKM dapat mengalokasikan dana untuk inovasi dan peningkatan kualitas produk. Selain itu, sistem pengiriman yang semakin efisien memungkinkan UKM memenuhi pesanan dengan lebih cepat dan tepat waktu.</p><p>Selain akses pasar yang lebih luas, sistem pembayaran digital juga telah meningkatkan efisiensi transaksi keuangan. Penggunaan dompet digital dan pembayaran nontunai tidak hanya mempermudah konsumen dalam berbelanja, tetapi juga membantu UKM dalam mencatat keuangan secara lebih akurat. Keuntungan lain dari ekonomi digital adalah strategi pemasaran berbasis data. Melalui analisis data pelanggan, UKM dapat memahami tren pasar dan perilaku konsumen dengan lebih baik. Misalnya, penggunaan iklan digital yang ditargetkan memungkinkan UKM menjangkau segmen pasar yang lebih spesifik sehingga efektivitas promosi meningkat.</p><p> Meskipun menawarkan banyak manfaat, transformasi digital juga menghadirkan tantangan. UKM harus mampu beradaptasi dengan perkembangan teknologi dan meningkatkan literasi digital agar tetap kompetitif. Selain itu, keamanan data menjadi aspek penting yang harus diperhatikan dalam menjalankan bisnis secara digital untuk menghindari risiko peretasan dan penyalahgunaan informasi pelanggan. Dengan segala peluang dan tantangannya, ekonomi digital telah menjadi faktor kunci dalam mendorong pertumbuhan UKM. Jika dikelola dengan baik, digitalisasi dapat menjadi pendorong utama bagi keberlanjutan dan daya saing usaha kecil di era modern ini.</p><p> (Sumber: Kementerian Koperasi dan UKM Republik Indonesia)</p>', 3) on conflict (id) do update set subject_id = excluded.subject_id, label = excluded.label, body_html = excluded.body_html, sort_order = excluded.sort_order;
insert into public.passages (id, subject_id, label, body_html, sort_order) values ('psg-tka-bahasa-indonesia-sma-bacaan_05', 'sub-bahasa-indonesia-sma', 'Hampir 25 tahun lalu kami berpisah karena keluarga saya harus boyongan ke kota tempat kerja Ayah yan', '<p>Hampir 25 tahun lalu kami berpisah karena keluarga saya harus boyongan ke kota tempat kerja Ayah yang baru di luar pulau. Tak satupun barang tertinggal di rumah lama. Begitu juga dengan sahabatku, kami harus berpisah.</p><p>Bertemu dengannya setelah sekian lama, mengingatkan kembali pada pengalaman kami dahulu. Pengalaman yang menjadikan dia, walau tidak setiap waktu, selalu lekat di ingatan saya. Tentu dia mengingatnya pula, bahkan saya yakin rasa yang diidapnya lebih besar efeknya. Karena sebagai seorang sahabat, dia jelas jauh lebih tulus dan setia daripada saya. Tak terasa mata saya mulai berkaca- kaca.</p><p>Saat malam itu saya berada di sini, memperhatikannya belajar. Selesai belajar, dia menyuruh saya pulang karena hendak pergi mencari jangkrik. Saya langsung menyatakan ingin ikut, tapi dia keberatan. Ayah dan ibunya pun melarang. Saya sering mendengar cerita mengasyikan anak-anak beramai-ramai berangkat ke sawah selepas isya untuk mencari jangkrik. Sayang, Ayah tidak pernah membolehkan saya. Tapi malam itu saya nekat dan sahabat saya itu akhirnya tidak kuasa menolak. ”Tidak ganti baju?” tanya saya heran begitu dia langsung memimpin untuk berangkat. Itu hari Jumat. Seragam coklat Pramuka yang dikenakannya sejak pagi masih akan terpakai untuk bersekolah sehari lagi. Dia memang tidak memiliki banyak pakaian hingga seragam sekolah biasa dipakai kapan saja. Tapi memakainya untuk pergi ke sawah mencari jangkrik, rasanya sangat tidak elok.</p>', 4) on conflict (id) do update set subject_id = excluded.subject_id, label = excluded.label, body_html = excluded.body_html, sort_order = excluded.sort_order;
insert into public.passages (id, subject_id, label, body_html, sort_order) values ('psg-tka-bahasa-indonesia-sma-bacaan_06', 'sub-bahasa-indonesia-sma', 'Teks untuk soal nomor 17 s.d. 20!', '<p><strong>Teks untuk soal nomor 17 s.d. 20!</strong></p><p>(1) Perubahan iklim yang semakin nyata dan ancaman terhadap kelestarian bumi menuntut kita untuk mencari solusi efektif dalam menjaga keseimbangan alam. (2) Salah satu solusi yang paling menjanjikan adalah penggunaan teknologi hijau. (3) Teknologi hijau juga dikenal sebagai teknologi ramah lingkungan. (4) Teknologi ini merupakan inovasi yang dirancang untuk mengatasi berbagai tantangan lingkungan global, terutama terkait dengan perubahan iklim.</p><p>(1) Perubahan iklim, yang dipicu oleh peningkatan emisi gas rumah kaca akibat aktivitas manusia, menyebabkan cuaca ekstrem, suhu global yang meningkat, dan naiknya permukaan air laut. (2) Hal tersebut juga memicu deforestasi, polusi, dan mengancam keberagaman hayati di seluruh dunia. (3) Oleh karena itu, kita harus mengambil langkah tegas agar dampak perubahan iklim ini tidak semakin parah. (4) Teknologi hijau seperti energi terbarukan (tenaga surya, angin) dapat mengurangi ketergantungan pada bahan bakar fosil yang menjadi penyebab utama emisi gas rumah kaca planet ini.</p><p>(1) Teknologi hijau juga sangat penting dalam upaya adaptasi terhadap dampak perubahan iklim yang sudah tidak bisa dihindari. (2) Sistem pertanian presisi, infrastruktur tahan bencana alam, serta teknologi untuk menginvestigasi banjir dan kekeringan adalah contoh bagaimana teknologi hijau bisa membantu masyarakat beradaptasi dengan kondisi yang berubah.</p><p>(1) Dengan kondisi bumi yang semakin menghadapi tantangan besar, seperti pemanasan global, polusi, kelangkaan sumber daya, dan hilangnya keanekaragaman hayati, penerapan teknologi hijau adalah keharusan. (2) Melalui teknologi hijau, kita dapat mengurangi dampak negatif terhadap lingkungan dan memperbaiki kualitas hidup.</p><p>Sumber: https://www.rri.co.id/iptek/1281411/</p>', 5) on conflict (id) do update set subject_id = excluded.subject_id, label = excluded.label, body_html = excluded.body_html, sort_order = excluded.sort_order;
insert into public.questions (id, subject_id, topic_id, subtopic_id, type, competency, content_format, passage_id, question_text, explanation, options, correct_answer, correct_answers, categories, statements, source_answer_key) values ('tka-bahasa-indonesia-sma-001', 'sub-bahasa-indonesia-sma', 'top-bahasa-indonesia-sma-01', 'st-bahasa-indonesia-sma-01', 'single', 'Pemahaman Tekstual', 'html', 'psg-tka-bahasa-indonesia-sma-bacaan_01', '<p>Makna istilah <em>mobilisasi </em>pada paragraf kedua teks tersebut adalah ....</p>', null, '[{"key":"A","text":"<p>bergerak bersama </p>"},{"key":"B","text":"<p>melangkah cepat</p>"},{"key":"C","text":"<p>beradu cepat</p>"},{"key":"D","text":"<p>mengatur bersama</p>"},{"key":"E","text":"<p>berpikir bersama</p>"}]'::jsonb, 'A', null, null, null, 'A') on conflict (id) do update set subject_id = excluded.subject_id, topic_id = excluded.topic_id, subtopic_id = excluded.subtopic_id, type = excluded.type, competency = excluded.competency, content_format = excluded.content_format, passage_id = excluded.passage_id, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, correct_answers = excluded.correct_answers, categories = excluded.categories, statements = excluded.statements, source_answer_key = excluded.source_answer_key, updated_at = now();
insert into public.questions (id, subject_id, topic_id, subtopic_id, type, competency, content_format, passage_id, question_text, explanation, options, correct_answer, correct_answers, categories, statements, source_answer_key) values ('tka-bahasa-indonesia-sma-002', 'sub-bahasa-indonesia-sma', 'top-bahasa-indonesia-sma-02', 'st-bahasa-indonesia-sma-02', 'single', 'Pemahaman Inferensial', 'html', 'psg-tka-bahasa-indonesia-sma-bacaan_01', '<p>Apa gagasan utama yang disampaikan pada paragraf pertama teks tersebut?</p>', null, '[{"key":"A","text":"<p>Ancaman plastik terhadap lautan.</p>"},{"key":"B","text":"<p>Efek dari pemanasan laut.</p>"},{"key":"C","text":"<p>Kadar tingkat keasaman laut.</p>"},{"key":"D","text":"<p>Pemompaan CO<sub>2</sub> ke atmosfer.</p>"},{"key":"E","text":"<p>Ancaman bagi negara berkembang.</p>"}]'::jsonb, 'A', null, null, null, 'A') on conflict (id) do update set subject_id = excluded.subject_id, topic_id = excluded.topic_id, subtopic_id = excluded.subtopic_id, type = excluded.type, competency = excluded.competency, content_format = excluded.content_format, passage_id = excluded.passage_id, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, correct_answers = excluded.correct_answers, categories = excluded.categories, statements = excluded.statements, source_answer_key = excluded.source_answer_key, updated_at = now();
insert into public.questions (id, subject_id, topic_id, subtopic_id, type, competency, content_format, passage_id, question_text, explanation, options, correct_answer, correct_answers, categories, statements, source_answer_key) values ('tka-bahasa-indonesia-sma-003', 'sub-bahasa-indonesia-sma', 'top-bahasa-indonesia-sma-03', 'st-bahasa-indonesia-sma-03', 'mcma', 'Pemahaman Literal', 'html', 'psg-tka-bahasa-indonesia-sma-bacaan_01', '<p>Mengapa lautan menghadapi ancaman pada 2050?</p><p>Pilihlah jawaban yang benar! Jawaban benar lebih dari satu.</p>', null, '[{"key":"A","text":"<p>Sampah plastik di laut akan lebih banyak daripada jumlah ikan.</p>"},{"key":"B","text":"<p>Lautan akan terus mengalami pemanasan dan semakin asam.</p>"},{"key":"C","text":"<p>Manusia terus memompa lebih banyak CO<sub>2</sub> ke atmosfer.</p>"},{"key":"D","text":"<p>Jumlah ikan yang terancam punah semakin banyak.</p>"},{"key":"E","text":"<p>Penggunaan plastik terus meningkat dan tidak dikelola dengan baik</p>"}]'::jsonb, null, array['A','E']::text[], null, null, 'A, E') on conflict (id) do update set subject_id = excluded.subject_id, topic_id = excluded.topic_id, subtopic_id = excluded.subtopic_id, type = excluded.type, competency = excluded.competency, content_format = excluded.content_format, passage_id = excluded.passage_id, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, correct_answers = excluded.correct_answers, categories = excluded.categories, statements = excluded.statements, source_answer_key = excluded.source_answer_key, updated_at = now();
insert into public.questions (id, subject_id, topic_id, subtopic_id, type, competency, content_format, passage_id, question_text, explanation, options, correct_answer, correct_answers, categories, statements, source_answer_key) values ('tka-bahasa-indonesia-sma-004', 'sub-bahasa-indonesia-sma', 'top-bahasa-indonesia-sma-04', 'st-bahasa-indonesia-sma-04', 'category', 'Evaluasi dan Apresiasi', 'html', 'psg-tka-bahasa-indonesia-sma-bacaan_01', '<p>“Solusi tersebut tidak mudah.”</p><p>Mengapa penulis menggunakan kalimat tersebut pada teks?</p><p>Tentukan <strong>Benar</strong> atau <strong>Salah</strong> untuk setiap pernyataan berikut!</p>', null, null, null, null, '[{"key":"benar","label":"Benar"},{"key":"salah","label":"Salah"}]'::jsonb, '[{"id":"A","text":"<p>Menginformasikan kepada pembaca bahwa pemecahan masalah sampah merupakan tanggung jawab utama kita sebagai masyarakat sipil sehingga sulit untuk diselesaikan.</p>","correctCategoryKey":"salah"},{"id":"B","text":"<p>Menunjukkan kepada pembaca bahwa permasalahan sampah plastik sangat rumit dan tidak bisa diselesaikan dalam jangka waktu singkat.</p>","correctCategoryKey":"benar"},{"id":"C","text":"<p>Membuktikan kepada pembaca bahwa permasalahan sampah yang rumit disebabkan pemecahan masalah yang bergantung pada perekonomian negara berkembang.</p>","correctCategoryKey":"salah"}]'::jsonb, 'Pernyataan A. Salah B. Benar C. Salah') on conflict (id) do update set subject_id = excluded.subject_id, topic_id = excluded.topic_id, subtopic_id = excluded.subtopic_id, type = excluded.type, competency = excluded.competency, content_format = excluded.content_format, passage_id = excluded.passage_id, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, correct_answers = excluded.correct_answers, categories = excluded.categories, statements = excluded.statements, source_answer_key = excluded.source_answer_key, updated_at = now();
insert into public.questions (id, subject_id, topic_id, subtopic_id, type, competency, content_format, passage_id, question_text, explanation, options, correct_answer, correct_answers, categories, statements, source_answer_key) values ('tka-bahasa-indonesia-sma-005', 'sub-bahasa-indonesia-sma', 'top-bahasa-indonesia-sma-02', 'st-bahasa-indonesia-sma-02', 'category', 'Pemahaman Inferensial', 'html', 'psg-tka-bahasa-indonesia-sma-bacaan_02', '<p>Apa permasalahan yang dihadapi tokoh aku dalam kutipan tersebut?</p><p>Tentukan <strong>Benar</strong> atau <strong>Salah</strong> untuk setiap pernyataan berikut!</p>', null, null, null, null, '[{"key":"benar","label":"Benar"},{"key":"salah","label":"Salah"}]'::jsonb, '[{"id":"A","text":"<p>Kekecewaan dan kesedihan tokoh aku terhadap sikap Ayahnya yang tidak mengizinkannya masuk sekolah di musim <em>maddongi, </em>padahal dia harus mempersiapkan diri untuk bersaing dalam lomba dengan siswa sekolah lain.</p>","correctCategoryKey":"benar"},{"id":"B","text":"<p>Kemarahan hati tokoh aku terhadap Ayahnya yang melarang dia pergi sekolah karena sedang musim <em>maddongi </em>di sawah dan dia diberi tugas menghalau burung yang hinggap pada padi di sawah mereka.</p>","correctCategoryKey":"salah"},{"id":"C","text":"<p>Perasaan tertekan tokoh aku terhadap peraturan keluarganya yang mengharuskan dia tidak masuk sekolah setiap musim <em>maddongi, </em>padahal dia ingin sekali belajar dan tidak mau ketinggalan pelajaran.</p>","correctCategoryKey":"salah"}]'::jsonb, 'Pernyataan A. Benar B. Salah C. Salah') on conflict (id) do update set subject_id = excluded.subject_id, topic_id = excluded.topic_id, subtopic_id = excluded.subtopic_id, type = excluded.type, competency = excluded.competency, content_format = excluded.content_format, passage_id = excluded.passage_id, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, correct_answers = excluded.correct_answers, categories = excluded.categories, statements = excluded.statements, source_answer_key = excluded.source_answer_key, updated_at = now();
insert into public.questions (id, subject_id, topic_id, subtopic_id, type, competency, content_format, passage_id, question_text, explanation, options, correct_answer, correct_answers, categories, statements, source_answer_key) values ('tka-bahasa-indonesia-sma-006', 'sub-bahasa-indonesia-sma', 'top-bahasa-indonesia-sma-02', 'st-bahasa-indonesia-sma-05', 'mcma', 'Pemahaman Inferensial', 'html', 'psg-tka-bahasa-indonesia-sma-bacaan_02', '<p>Apa yang akan terjadi jika tokoh aku tidak datang ke rumah <em>iyye</em>?</p><p>Pilihlah jawaban yang benar! Jawaban benar lebih dari satu.</p>', null, '[{"key":"A","text":"<p><em>Iyye</em> akan datang menasehati Ayah karena melarang tokoh aku untuk belajar.</p>"},{"key":"B","text":"<p>Tokoh aku akan kehilangan kesempatan belajar untuk mengikuti</p>"},{"key":"C","text":"<p>Ayah akan tetap melarang tokoh aku untuk belajar dan mengikuti lomba.</p>"},{"key":"D","text":"<p>Permasalahan tokoh aku dan ayah akan berlarut karena tidak terselesaikan.</p>"},{"key":"E","text":"<p>Tokoh aku tidak akan bisa fokus untuk belajar dan mengikuti lomba yang diadakan sekolah.</p>"}]'::jsonb, null, array['B','D']::text[], null, null, 'B, D') on conflict (id) do update set subject_id = excluded.subject_id, topic_id = excluded.topic_id, subtopic_id = excluded.subtopic_id, type = excluded.type, competency = excluded.competency, content_format = excluded.content_format, passage_id = excluded.passage_id, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, correct_answers = excluded.correct_answers, categories = excluded.categories, statements = excluded.statements, source_answer_key = excluded.source_answer_key, updated_at = now();
insert into public.questions (id, subject_id, topic_id, subtopic_id, type, competency, content_format, passage_id, question_text, explanation, options, correct_answer, correct_answers, categories, statements, source_answer_key) values ('tka-bahasa-indonesia-sma-007', 'sub-bahasa-indonesia-sma', 'top-bahasa-indonesia-sma-04', 'st-bahasa-indonesia-sma-06', 'single', 'Evaluasi dan Apresiasi', 'html', 'psg-tka-bahasa-indonesia-sma-bacaan_02', '<p>Keterkaitan nilai sosial dalam kutipan cerpen tersebut dengan kehidupan sehari-hari adalah …</p>', null, '[{"key":"A","text":"<p>Masih ditemukan orang tua yang tidak memedulikan pendidikan anaknya demi membantu pekerjaan mereka.</p>"},{"key":"B","text":"<p>Terbenturnya cita-cita anak karena tradisi sebuah keluarga yang mengutamakan anak mampu bekerja mandiri.</p>"},{"key":"C","text":"<p>Asumsi bahwa bekerja lebih bermanfaat daripada sekolah yang dianggap tidak menghasilkan apa-apa untuk keluarga.</p>"},{"key":"D","text":"<p>Kebiasaan anak-anak tidak sekolah di musim <em>maddongi </em>demi menjalankan tradisi di lingkungan keluarga mereka.</p>"},{"key":"E","text":"<p>Orang tua mengarahkan anak-anak untuk rajin bekerja membantu mereka di sawah agar bisa melanjutkan kehidupannya kelak.</p>"}]'::jsonb, 'A', null, null, null, 'A') on conflict (id) do update set subject_id = excluded.subject_id, topic_id = excluded.topic_id, subtopic_id = excluded.subtopic_id, type = excluded.type, competency = excluded.competency, content_format = excluded.content_format, passage_id = excluded.passage_id, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, correct_answers = excluded.correct_answers, categories = excluded.categories, statements = excluded.statements, source_answer_key = excluded.source_answer_key, updated_at = now();
insert into public.questions (id, subject_id, topic_id, subtopic_id, type, competency, content_format, passage_id, question_text, explanation, options, correct_answer, correct_answers, categories, statements, source_answer_key) values ('tka-bahasa-indonesia-sma-008', 'sub-bahasa-indonesia-sma', 'top-bahasa-indonesia-sma-02', 'st-bahasa-indonesia-sma-07', 'single', 'Pemahaman Inferensial', 'html', 'psg-tka-bahasa-indonesia-sma-bacaan_03', '<p>Tujuan penulis sesuai teks 1 adalah ...</p>', null, '[{"key":"A","text":"<p>Menginformasikan jenis dan rasa makanan yang mengandung Rhodamin B.</p>"},{"key":"B","text":"<p>Menjelaskan dampak penggunaan Rhodamin B pada bahan-bahan industri.</p>"},{"key":"C","text":"<p>Mengimbau agar masyarakat tidak menggunakan barang-barang yang mengandung Rhodamin B.</p>"},{"key":"D","text":"<p>Menginformasikan dampak mengonsumsi makanan yang mengandung Rhodamin B bagi tubuh.</p>"},{"key":"E","text":"<p>Menjelaskan gejala yang timbul akibat mengkonsumsi makanan yang mengandung Rhodamin B.</p>"}]'::jsonb, 'D', null, null, null, 'D') on conflict (id) do update set subject_id = excluded.subject_id, topic_id = excluded.topic_id, subtopic_id = excluded.subtopic_id, type = excluded.type, competency = excluded.competency, content_format = excluded.content_format, passage_id = excluded.passage_id, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, correct_answers = excluded.correct_answers, categories = excluded.categories, statements = excluded.statements, source_answer_key = excluded.source_answer_key, updated_at = now();
insert into public.questions (id, subject_id, topic_id, subtopic_id, type, competency, content_format, passage_id, question_text, explanation, options, correct_answer, correct_answers, categories, statements, source_answer_key) values ('tka-bahasa-indonesia-sma-009', 'sub-bahasa-indonesia-sma', 'top-bahasa-indonesia-sma-02', 'st-bahasa-indonesia-sma-08', 'single', 'Pemahaman Inferensial', 'html', 'psg-tka-bahasa-indonesia-sma-bacaan_03', '<p>Pernyataan yang tepat sesuai isi kedua teks tersebut berkaitan dengan Rhodamin B adalah ...</p>', null, '[{"key":"A","text":"<p>Rhodamin B sering disalahgunakan sebagai pewarna makanan karena menawarkan cita rasa yang tinggi.</p>"},{"key":"B","text":"<p>Rhodamin B berdampak buruk bagi kesehatan, tetapi diperlukan pada industri, seperti tekstil dan kertas.</p>"},{"key":"C","text":"<p>Rhodamin B berdampak buruk bagi kesehatan, tetapi mudah ditemukan pada kembang gula dan sirup.</p>"},{"key":"D","text":"<p>Rhodamin B yang berbentuk serbuk kristal dan berwarna hijau digunakan pada industri tekstil dan kertas.</p>"},{"key":"E","text":"<p>Rhodamin B berdampak buruk bagi kesehatan, meskipun dampak itu baru terlihat beberapa tahun kemudian.</p>"}]'::jsonb, 'B', null, null, null, 'B') on conflict (id) do update set subject_id = excluded.subject_id, topic_id = excluded.topic_id, subtopic_id = excluded.subtopic_id, type = excluded.type, competency = excluded.competency, content_format = excluded.content_format, passage_id = excluded.passage_id, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, correct_answers = excluded.correct_answers, categories = excluded.categories, statements = excluded.statements, source_answer_key = excluded.source_answer_key, updated_at = now();
insert into public.questions (id, subject_id, topic_id, subtopic_id, type, competency, content_format, passage_id, question_text, explanation, options, correct_answer, correct_answers, categories, statements, source_answer_key) values ('tka-bahasa-indonesia-sma-010', 'sub-bahasa-indonesia-sma', 'top-bahasa-indonesia-sma-04', 'st-bahasa-indonesia-sma-09', 'mcma', 'Evaluasi dan Apresiasi', 'html', 'psg-tka-bahasa-indonesia-sma-bacaan_03', '<p>Mengapa kedua teks tersebut menyebutkan dampak kesehatan yang timbul dari konsumsi pangan yang terkontaminasi Rhodamin B?</p><p>Pilihlah jawaban yang benar! Jawaban benar lebih dari satu.</p>', null, '[{"key":"A","text":"<p>Mendorong masyarakat untuk menghindari Rhodamin B dalam berbagai keperluan.</p>"},{"key":"B","text":"<p>Meningkatkan kesadaran masyarakat tentang bahaya Rhodamin B dalam makanan</p>"},{"key":"C","text":"<p>Menunjukkan bahwa Rhodamin B aman digunakan dalam industri tekstil dan kertas.</p>"},{"key":"D","text":"<p>Menjelaskan bahwa Rhodamin B adalah zat berbahaya jika dikonsumsi, terutama dalam jangka panjang.</p>"},{"key":"E","text":"<p>Memperingatkan masyarakat agar menghindari makanan berwarna mencolok yang berisiko mengandung Rhodamin B.</p>"}]'::jsonb, null, array['B','D','E']::text[], null, null, 'B, D, E') on conflict (id) do update set subject_id = excluded.subject_id, topic_id = excluded.topic_id, subtopic_id = excluded.subtopic_id, type = excluded.type, competency = excluded.competency, content_format = excluded.content_format, passage_id = excluded.passage_id, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, correct_answers = excluded.correct_answers, categories = excluded.categories, statements = excluded.statements, source_answer_key = excluded.source_answer_key, updated_at = now();
insert into public.questions (id, subject_id, topic_id, subtopic_id, type, competency, content_format, passage_id, question_text, explanation, options, correct_answer, correct_answers, categories, statements, source_answer_key) values ('tka-bahasa-indonesia-sma-011', 'sub-bahasa-indonesia-sma', 'top-bahasa-indonesia-sma-01', 'st-bahasa-indonesia-sma-10', 'single', 'Pemahaman Tekstual', 'html', 'psg-tka-bahasa-indonesia-sma-bacaan_04', '<p>Bagan yang tepat untuk menggambarkan bagian-bagian penting dalam teks tersebut adalah ….</p>', null, '[{"key":"A","text":"<p><img src=\"/soal/25068_description.png\" alt=\"Description\"/></p>"},{"key":"B","text":"<p><img src=\"/soal/25068_49ab5357d2bcbdb2bccfaa5f4d128808.png\" alt=\"\"/></p>"},{"key":"C","text":"<p><img src=\"/soal/25068_0a1d331f78fb32852fef358c2ce0a1c1.png\" alt=\"\"/></p>"},{"key":"D","text":"<p><img src=\"/soal/25068_ee9e5d7c03f2925e48144abb2723c967.png\" alt=\"\"/></p>"},{"key":"E","text":"<p><img src=\"/soal/25068_da11f9711461225e3ac115058b1f008d.png\" alt=\"\"/></p>"}]'::jsonb, 'A', null, null, null, 'A') on conflict (id) do update set subject_id = excluded.subject_id, topic_id = excluded.topic_id, subtopic_id = excluded.subtopic_id, type = excluded.type, competency = excluded.competency, content_format = excluded.content_format, passage_id = excluded.passage_id, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, correct_answers = excluded.correct_answers, categories = excluded.categories, statements = excluded.statements, source_answer_key = excluded.source_answer_key, updated_at = now();
insert into public.questions (id, subject_id, topic_id, subtopic_id, type, competency, content_format, passage_id, question_text, explanation, options, correct_answer, correct_answers, categories, statements, source_answer_key) values ('tka-bahasa-indonesia-sma-012', 'sub-bahasa-indonesia-sma', 'top-bahasa-indonesia-sma-02', 'st-bahasa-indonesia-sma-08', 'category', 'Pemahaman Inferensial', 'html', 'psg-tka-bahasa-indonesia-sma-bacaan_04', '<p>Bagaimana pola pengembangan paragraf ke-1, ke-2, dan ke-3 pada teks tersebut? <br/>Tentukan Benar atau Salah untuk setiap pernyataan berdasarkan isi teks!</p>', null, null, null, null, '[{"key":"benar","label":"Benar"},{"key":"salah","label":"Salah"}]'::jsonb, '[{"id":"A","text":"<p>Paragraf pertama (1) menggunakan pola sebab-akibat karena menjelaskan bagaimana teknologi digital menyebabkan perubahan bagi UKM.</p>","correctCategoryKey":"benar"},{"id":"B","text":"<p>Paragraf kedua (2) menggunakan pola proses karena menjelaskan langkah-langkah bagaimana UKM memanfaatkan <em>e-commerce</em>.</p>","correctCategoryKey":"benar"},{"id":"C","text":"<p>Paragraf ketiga (3) menggunakan pola klasifikasi karena membagi sistem pembayaran UKM menjadi beberapa kategori yang berbeda.</p>","correctCategoryKey":"salah"}]'::jsonb, 'Pernyataan A. Benar B. Benar C. Salah') on conflict (id) do update set subject_id = excluded.subject_id, topic_id = excluded.topic_id, subtopic_id = excluded.subtopic_id, type = excluded.type, competency = excluded.competency, content_format = excluded.content_format, passage_id = excluded.passage_id, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, correct_answers = excluded.correct_answers, categories = excluded.categories, statements = excluded.statements, source_answer_key = excluded.source_answer_key, updated_at = now();
insert into public.questions (id, subject_id, topic_id, subtopic_id, type, competency, content_format, passage_id, question_text, explanation, options, correct_answer, correct_answers, categories, statements, source_answer_key) values ('tka-bahasa-indonesia-sma-013', 'sub-bahasa-indonesia-sma', 'top-bahasa-indonesia-sma-04', 'st-bahasa-indonesia-sma-09', 'category', 'Evaluasi dan Apresiasi', 'html', 'psg-tka-bahasa-indonesia-sma-bacaan_04', '<p>Dini : Teks tersebut sangat menarik dan bisa menambah wawasan kita, terutama jika kita berencana untuk mengembangkan suatu bisnis kecil.</p><p>Rio : Iya, pilihan katanya juga sangat mudah dimengerti sehingga orang yang awam terhadap istilah di bidang ekonomi juga mudah untuk memahami isi informasi yang disajikan.</p><p>Sena : Aku sependapat dengan kalian berdua, tetapi rasanya teks tersebut akan lebih baik jika disertai data pertumbuhan UKM dalam kurun waktu lima tahun terakhir atau pendapat ahli di bidang ekonomi.</p><p>Berdasarkan percakapan tersebut, mengapa pendapat Sena sangat baik dalam menilai keakuratan dari informasi yang disajikan tersebut?</p>', null, null, null, null, '[{"key":"tidak-setuju","label":"Tidak Setuju"},{"key":"setuju","label":"Setuju"}]'::jsonb, '[{"id":"A","text":"<p>Sena menyoroti bahwa teks harus mudah dipahami oleh semua kalangan, termasuk yang awam terhadap ekonomi.</p>","correctCategoryKey":"tidak-setuju"},{"id":"B","text":"<p>Sena mempertimbangkan kelengkapan dan dasar bukti dari informasi yang merupakan bagian dari menilai keakuratan teks.</p>","correctCategoryKey":"setuju"},{"id":"C","text":"<p>Sena memiliki inisiatif untuk memperbaiki isi teks dengan pendapat pribadinya sebagai ahli ekonomi agar lebih informatif.</p>","correctCategoryKey":"tidak-setuju"}]'::jsonb, 'Alasan A. Tidak Setuju B. Setuju C. Tidak Setuju') on conflict (id) do update set subject_id = excluded.subject_id, topic_id = excluded.topic_id, subtopic_id = excluded.subtopic_id, type = excluded.type, competency = excluded.competency, content_format = excluded.content_format, passage_id = excluded.passage_id, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, correct_answers = excluded.correct_answers, categories = excluded.categories, statements = excluded.statements, source_answer_key = excluded.source_answer_key, updated_at = now();
insert into public.questions (id, subject_id, topic_id, subtopic_id, type, competency, content_format, passage_id, question_text, explanation, options, correct_answer, correct_answers, categories, statements, source_answer_key) values ('tka-bahasa-indonesia-sma-014', 'sub-bahasa-indonesia-sma', 'top-bahasa-indonesia-sma-01', 'st-bahasa-indonesia-sma-01', 'single', 'Pemahaman Tekstual', 'html', 'psg-tka-bahasa-indonesia-sma-bacaan_05', '<p>Saya mengambil alih obor dari tangannya. Rasanya belum terlalu lama kami berada di sana dan bumbung baru terisi beberapa ekor jangkrik ketika tiba-tiba angin berubah perangai. Kaget, pantat obor itu justru saya angkat tinggi-tinggi sehingga minyak mendorong sumbunya terlepas. Api dengan cepat berpindah membakar punggung saya! Terdengar teriakannya sembari melepaskan seragam coklatnya untuk dipakai menyabet punggung saya. Baju yang saya kenakan habis sepertiganya. Sahabat saya itu tanggap melingkupi tubuh saya dengan seragam coklatnya melihat saya mulai menangis.</p><p>dan menggigil antara kesakitan dan kedinginan. Sadar saya membutuhkan pertolongan secepatnya, dia menggendong saya lalu berlari sembari membujuk-bujuk saya untuk tetap tenang. Napasnya memburu kelelahan, tapi rasa tanggung jawab yang besar seperti memberinya kekuatan berlipat untuk tetap bersama saya.<br/>(Kutipan Cerpen <em>Seragam </em>karya Aris Kurniawan Basuki dengan penyesuaian)</p><p>“Hampir 25 tahun lalu kami berpisah karena keluarga saya harus boyongan ke kota tempat kerja Ayah yang baru di luar pulau.”</p><p>Penggunaan kata serapan <strong>boyongan</strong> dapat memperjelas peristiwa yang dialami tokoh saya, yaitu ...</p>', null, '[{"key":"A","text":"<p>Peristiwa pindahan yang sering dialami pegawai suatu instansi untuk kepentingan promosi jabatan.</p>"},{"key":"B","text":"<p>Peristiwa pindah rumah dari kampung halaman ke tempat yang jauh untuk jangka waktu lama.</p>"},{"key":"C","text":"<p>Pindah rumah bersama seluruh anggota keluarga dengan membawa semua barang rumah tangga.</p>"},{"key":"D","text":"<p>Pindah rumah untuk mengikuti tugas kedinasan orang tua di tempat baru yang letaknya sangat jauh.</p>"},{"key":"E","text":"<p>Kegiatan pindah rumah untuk sementara waktu dan akan berpindah lagi ke rumah dinas yang lain.</p>"}]'::jsonb, 'C', null, null, null, 'C') on conflict (id) do update set subject_id = excluded.subject_id, topic_id = excluded.topic_id, subtopic_id = excluded.subtopic_id, type = excluded.type, competency = excluded.competency, content_format = excluded.content_format, passage_id = excluded.passage_id, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, correct_answers = excluded.correct_answers, categories = excluded.categories, statements = excluded.statements, source_answer_key = excluded.source_answer_key, updated_at = now();
insert into public.questions (id, subject_id, topic_id, subtopic_id, type, competency, content_format, passage_id, question_text, explanation, options, correct_answer, correct_answers, categories, statements, source_answer_key) values ('tka-bahasa-indonesia-sma-015', 'sub-bahasa-indonesia-sma', 'top-bahasa-indonesia-sma-02', 'st-bahasa-indonesia-sma-05', 'category', 'Pemahaman Inferensial', 'html', 'psg-tka-bahasa-indonesia-sma-bacaan_05', '<p>Saya mengambil alih obor dari tangannya. Rasanya belum terlalu lama kami berada di sana dan bumbung baru terisi beberapa ekor jangkrik ketika tiba-tiba angin berubah perangai. Kaget, pantat obor itu justru saya angkat tinggi-tinggi sehingga minyak mendorong sumbunya terlepas. Api dengan cepat berpindah membakar punggung saya! Terdengar teriakannya sembari melepaskan seragam coklatnya untuk dipakai menyabet punggung saya. Baju yang saya kenakan habis sepertiganya. Sahabat saya itu tanggap melingkupi tubuh saya dengan seragam coklatnya melihat saya mulai menangis.</p><p>dan menggigil antara kesakitan dan kedinginan. Sadar saya membutuhkan pertolongan secepatnya, dia menggendong saya lalu berlari sembari membujuk-bujuk saya untuk tetap tenang. Napasnya memburu kelelahan, tapi rasa tanggung jawab yang besar seperti memberinya kekuatan berlipat untuk tetap bersama saya.<br/>(Kutipan Cerpen <em>Seragam </em>karya Aris Kurniawan Basuki dengan penyesuaian)</p><p>Peristiwa apa yang mungkin akan terjadi kepada sahabatnya jika tokoh saya tidak ikut mencari jangkrik malam itu?<br/>Tentukan Tepat atau Tidak Tepat untuk setiap pernyataan berikut!</p>', null, null, null, null, '[{"key":"tepat","label":"Tepat"},{"key":"tidak-tepat","label":"Tidak Tepat"}]'::jsonb, '[{"id":"A","text":"<p>Sahabat tokoh saya masih memiliki seragam pramuka untuk dipakai.</p>","correctCategoryKey":"tepat"},{"id":"B","text":"<p>Punggung sahabat tokoh saya tidak akan memiliki luka bakar.</p>","correctCategoryKey":"tidak-tepat"},{"id":"C","text":"<p>Sahabat tokoh saya akan mencari jangkrik tanpa perlu berlari.</p>","correctCategoryKey":"tepat"}]'::jsonb, 'Pernyataan A. Tepat, B. Tidak Tepat C. Tepat') on conflict (id) do update set subject_id = excluded.subject_id, topic_id = excluded.topic_id, subtopic_id = excluded.subtopic_id, type = excluded.type, competency = excluded.competency, content_format = excluded.content_format, passage_id = excluded.passage_id, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, correct_answers = excluded.correct_answers, categories = excluded.categories, statements = excluded.statements, source_answer_key = excluded.source_answer_key, updated_at = now();
insert into public.questions (id, subject_id, topic_id, subtopic_id, type, competency, content_format, passage_id, question_text, explanation, options, correct_answer, correct_answers, categories, statements, source_answer_key) values ('tka-bahasa-indonesia-sma-016', 'sub-bahasa-indonesia-sma', 'top-bahasa-indonesia-sma-04', 'st-bahasa-indonesia-sma-11', 'mcma', 'Evaluasi dan Apresiasi', 'html', 'psg-tka-bahasa-indonesia-sma-bacaan_05', '<p>Saya mengambil alih obor dari tangannya. Rasanya belum terlalu lama kami berada di sana dan bumbung baru terisi beberapa ekor jangkrik ketika tiba-tiba angin berubah perangai. Kaget, pantat obor itu justru saya angkat tinggi-tinggi sehingga minyak mendorong sumbunya terlepas. Api dengan cepat berpindah membakar punggung saya! Terdengar teriakannya sembari melepaskan seragam coklatnya untuk dipakai menyabet punggung saya. Baju yang saya kenakan habis sepertiganya. Sahabat saya itu tanggap melingkupi tubuh saya dengan seragam coklatnya melihat saya mulai menangis.<br/>dan menggigil antara kesakitan dan kedinginan. Sadar saya membutuhkan pertolongan secepatnya, dia menggendong saya lalu berlari sembari membujuk-bujuk saya untuk tetap tenang. Napasnya memburu kelelahan, tapi rasa tanggung jawab yang besar seperti memberinya kekuatan berlipat untuk tetap bersama saya.</p><p>Kalimat mana saja dari dalam kutipan cerpen tersebut yang membuktikan karakter sahabat tokoh saya merupakan seorang yang setia kawan?<br/>Pilihlah jawaban yang benar! Jawaban benar lebih dari satu.</p>', null, '[{"key":"A","text":"<p>Saya langsung menyatakan ingin ikut, tapi dia keberatan.</p>"},{"key":"B","text":"<p>Dia memang tidak memiliki banyak pakaian hingga seragam sekolah biasa dipakai kapan saja.</p>"},{"key":"C","text":"<p>Sahabat saya itu tanggap melingkupi tubuh saya dengan seragam coklatnya.</p>"},{"key":"D","text":"<p>Dia menggendong saya lalu berlari sembari membujuk-bujuk saya untuk tetap tenang.</p>"},{"key":"E","text":"<p>Rasa tanggung jawab yang besar seperti memberinya kekuatan berlipat untuk tetap bersama saya.</p>"}]'::jsonb, null, array['C','D','E']::text[], null, null, 'C,D, dan E') on conflict (id) do update set subject_id = excluded.subject_id, topic_id = excluded.topic_id, subtopic_id = excluded.subtopic_id, type = excluded.type, competency = excluded.competency, content_format = excluded.content_format, passage_id = excluded.passage_id, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, correct_answers = excluded.correct_answers, categories = excluded.categories, statements = excluded.statements, source_answer_key = excluded.source_answer_key, updated_at = now();
insert into public.questions (id, subject_id, topic_id, subtopic_id, type, competency, content_format, passage_id, question_text, explanation, options, correct_answer, correct_answers, categories, statements, source_answer_key) values ('tka-bahasa-indonesia-sma-017', 'sub-bahasa-indonesia-sma', 'top-bahasa-indonesia-sma-01', 'st-bahasa-indonesia-sma-01', 'category', 'Pemahaman Tekstual', 'html', 'psg-tka-bahasa-indonesia-sma-bacaan_06', '<p>Manakah kalimat yang memiliki penggunaan kata serapan yang tepat?</p><p>Tentukan <strong>Tepat</strong> atau <strong>Tidak Tepat</strong> pada setiap pernyataan berikut</p>', null, null, null, null, '[{"key":"tepat","label":"Tepat"},{"key":"tidak-tepat","label":"Tidak Tepat"}]'::jsonb, '[{"id":"A","text":"<p>Kata “deforestasi” pada kalimat (2) paragraf kedua.</p>","correctCategoryKey":"tepat"},{"id":"B","text":"<p>Kata “menginvestigasi” pada kalimat (2) paragraf ketiga.</p>","correctCategoryKey":"tidak-tepat"},{"id":"C","text":"<p>Kata “polusi” pada kalimat (1) paragraf keempat.</p>","correctCategoryKey":"tepat"}]'::jsonb, 'Kalimat A. Tepat B. Tidak Tepat C. Tepat') on conflict (id) do update set subject_id = excluded.subject_id, topic_id = excluded.topic_id, subtopic_id = excluded.subtopic_id, type = excluded.type, competency = excluded.competency, content_format = excluded.content_format, passage_id = excluded.passage_id, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, correct_answers = excluded.correct_answers, categories = excluded.categories, statements = excluded.statements, source_answer_key = excluded.source_answer_key, updated_at = now();
insert into public.questions (id, subject_id, topic_id, subtopic_id, type, competency, content_format, passage_id, question_text, explanation, options, correct_answer, correct_answers, categories, statements, source_answer_key) values ('tka-bahasa-indonesia-sma-018', 'sub-bahasa-indonesia-sma', 'top-bahasa-indonesia-sma-02', 'st-bahasa-indonesia-sma-12', 'single', 'Pemahaman Inferensial', 'html', 'psg-tka-bahasa-indonesia-sma-bacaan_06', '<p>Hubungan makna antara kalimat (2) dan (3) pada paragraf kedua adalah ….</p>', null, '[{"key":"A","text":"<p>Akibat-sebab yang diperkuat dengan contoh deforestasi dan kerusakan lingkungan</p>"},{"key":"B","text":"<p>Sebab-akibat yang mengajak pembaca untuk mengambil langkah tegas</p>"},{"key":"C","text":"<p>Penegasan yang diperinci dengan contoh konkret yang bisa diaplikasikan pembaca</p>"},{"key":"D","text":"<p>Perbandingan dari dua pandangan terkait dampak negatif deforestasi</p>"},{"key":"E","text":"<p>Penyimpulan bahwa teknologi hijau merupakan solusi masalah deforestasi</p>"}]'::jsonb, 'B', null, null, null, 'B') on conflict (id) do update set subject_id = excluded.subject_id, topic_id = excluded.topic_id, subtopic_id = excluded.subtopic_id, type = excluded.type, competency = excluded.competency, content_format = excluded.content_format, passage_id = excluded.passage_id, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, correct_answers = excluded.correct_answers, categories = excluded.categories, statements = excluded.statements, source_answer_key = excluded.source_answer_key, updated_at = now();
insert into public.questions (id, subject_id, topic_id, subtopic_id, type, competency, content_format, passage_id, question_text, explanation, options, correct_answer, correct_answers, categories, statements, source_answer_key) values ('tka-bahasa-indonesia-sma-019', 'sub-bahasa-indonesia-sma', 'top-bahasa-indonesia-sma-02', 'st-bahasa-indonesia-sma-13', 'single', 'Pemahaman Inferensial', 'html', 'psg-tka-bahasa-indonesia-sma-bacaan_06', '<p>Kalimat yang tepat untuk mengakhiri uraian pada paragraf keempat adalah …</p>', null, '[{"key":"A","text":"<p>Pada sisi lain, teknologi hijau memunculkan deforestasi dan polusi.</p>"},{"key":"B","text":"<p>Sehingga dampak negatif lingkungan berdampak pula pada kualitas hidup.</p>"},{"key":"C","text":"<p>Di samping itu, teknologi hijau dapat menciptakan dunia yang lebih baik untuk generasi yang akan datang.</p>"},{"key":"D","text":"<p>Di samping itu, bumi yang menggunakan teknologi hijau akan semakin menghadapi tantangan besar.</p>"},{"key":"E","text":"<p>Jadi, teknologi hijau berperan dalam menghilangnya keanekaragaman hayati.</p>"}]'::jsonb, 'C', null, null, null, 'C') on conflict (id) do update set subject_id = excluded.subject_id, topic_id = excluded.topic_id, subtopic_id = excluded.subtopic_id, type = excluded.type, competency = excluded.competency, content_format = excluded.content_format, passage_id = excluded.passage_id, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, correct_answers = excluded.correct_answers, categories = excluded.categories, statements = excluded.statements, source_answer_key = excluded.source_answer_key, updated_at = now();
insert into public.questions (id, subject_id, topic_id, subtopic_id, type, competency, content_format, passage_id, question_text, explanation, options, correct_answer, correct_answers, categories, statements, source_answer_key) values ('tka-bahasa-indonesia-sma-020', 'sub-bahasa-indonesia-sma', 'top-bahasa-indonesia-sma-04', 'st-bahasa-indonesia-sma-09', 'mcma', 'Evaluasi dan Apresiasi', 'html', 'psg-tka-bahasa-indonesia-sma-bacaan_06', '<p>Manakah fakta-fakta yang mendukung simpulan bahwa teknologi hijau berperan dalam perubahan iklim?</p><p>Pilihlah jawaban yang benar! Jawaban benar lebih dari satu.</p>', null, '[{"key":"A","text":"<p>Teknologi hijau merupakan inovasi yang dirancang untuk mengatasi berbagai tantangan lingkungan global, terutama terkait dengan perubahan iklim.</p>"},{"key":"B","text":"<p>Perubahan iklim, yang dipicu oleh peningkatan emisi gas rumah kaca akibat aktivitas manusia, menyebabkan cuaca ekstrem, suhu global menurun, dan naiknya permukaan air laut.</p>"},{"key":"C","text":"<p>Teknologi hijau seperti energi terbarukan (tenaga surya, angin) dapat mengurangi ketergantungan pada bahan bakar fosil.</p>"},{"key":"D","text":"<p>Teknologi hijau juga sangat penting dalam upaya adaptasi terhadap dampak perubahan teknologi yang sudah tidak bisa dihindari.</p>"},{"key":"E","text":"<p>Melalui teknologi hijau, kita dapat mengurangi dampak negatif terhadap lingkungan dan memperbaiki kualitas hidup.</p>"}]'::jsonb, null, array['A','C','E']::text[], null, null, 'A, C, dan E') on conflict (id) do update set subject_id = excluded.subject_id, topic_id = excluded.topic_id, subtopic_id = excluded.subtopic_id, type = excluded.type, competency = excluded.competency, content_format = excluded.content_format, passage_id = excluded.passage_id, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, correct_answers = excluded.correct_answers, categories = excluded.categories, statements = excluded.statements, source_answer_key = excluded.source_answer_key, updated_at = now();
